import 'dart:typed_data';

final _clock = Stopwatch()..start();
int floorInt(double value) => value.floor();
int readInt(Int32List values, int index) => values[index];
int nowStamp() => _clock.elapsedTicks;
double stampMs(int delta) => delta * 1000.0 / _clock.frequency;

// Matched headless game CPU workloads. Dart counterpart is generated by
// generate_game_dart.py; this is deliberately a restricted shared source.
abstract interface class GameWorld {
  double tick();
}

class GameActor {
  double x = 0.0;
  double y = 0.0;
  double vx = 0.0;
  double vy = 0.0;
  int phase = 0;
  void update(int f) {
    this.x += this.vx * 0.016666666666666666;
    this.y += this.vy * 0.016666666666666666;
  }
}

class DragActor extends GameActor {
  void update(int f) {
    this.vx = this.vx * 0.999 + ((f + this.phase) % 17 - 8) * 0.0001;
    this.vy = this.vy * 0.998 + 0.001;
    this.x += this.vx * 0.016666666666666666;
    this.y += this.vy * 0.016666666666666666;
  }
}

class SteeringActor extends GameActor {
  void update(int f) {
    this.vx += (this.x < 0.0 ? 1.0 : -1.0) * 0.002;
    this.vy += (this.y < 0.0 ? 1.0 : -1.0) * 0.002;
    this.x += this.vx * 0.016666666666666666;
    this.y += this.vy * 0.016666666666666666;
  }
}

class ActorWorld implements GameWorld {
  List<GameActor> actors = [];
  int frame = 0;
  ActorWorld() {
    for (int i = 0; i < 10000; i++) {
      final GameActor a = i % 3 == 0
          ? GameActor()
          : (i % 3 == 1 ? DragActor() : SteeringActor());
      a.x = (i % 251) - 125.0 + 0.1234;
      a.y = ((i * 17) % 251) - 125.0 + 0.4321;
      a.vx = (i % 19 - 9) * 0.25;
      a.vy = (i % 13 - 6) * 0.25;
      a.phase = i % 17;
      this.actors.add(a);
    }
  }
  double tick() {
    final f = this.frame++;
    double sum = 0.0;
    for (int i = 0; i < this.actors.length; i++) {
      final a = this.actors[i];
      a.update(f);
      if (a.x >= 128.0) a.x -= 256.0;
      if (a.x < -128.0) a.x += 256.0;
      if (a.y >= 128.0) a.y -= 256.0;
      if (a.y < -128.0) a.y += 256.0;
      sum += a.x * 0.125 + a.y * 0.0625 + a.vx * 0.5 + a.vy;
    }
    return sum;
  }
}

class ParticleWorld implements GameWorld {
  Float64List data = Float64List(50000 * 7);
  int frame = 0;
  ParticleWorld() {
    for (int i = 0; i < 50000; i++) this.spawn(i, 0);
  }
