}

class SceneWorld implements GameWorld {
  Float64List local = Float64List(8191 * 12);
  Float64List world = Float64List(8191 * 12);
  Int32List dirty = Int32List(8191);
  int frame = 0;
  SceneWorld() {
    final l = this.local;
    for (int i = 0; i < 8191; i++) {
      final b = i * 12;
      final r = (i % 7 - 3) * 0.001;
      l[b] = 1.0 + (i % 3) * 0.0001;
      l[b + 1] = -r;
      l[b + 2] = 0.001;
      l[b + 3] = (i % 17 - 8) * 0.25;
      l[b + 4] = r;
      l[b + 5] = 0.99995;
      l[b + 6] = -0.002;
      l[b + 7] = (i % 13 - 6) * 0.25;
      l[b + 8] = -0.001;
      l[b + 9] = 0.002;
      l[b + 10] = 1.0;
      l[b + 11] = (i % 11 - 5) * 0.25;
    }
  }
  double tick() {
    final f = this.frame++;
    final l = this.local;
    final w = this.world;
    final dirty = this.dirty;
    double sum = 0.0;
    for (int i = 0; i < 8191; i++) {
      final b = i * 12;
      final int parent = i == 0 ? -1 : floorInt((i - 1) * 0.5);
      final changed = (i + f) % 16 == 0;
      if (changed) {
        l[b + 3] += 0.001;
        if (l[b + 3] > 8.0) l[b + 3] -= 16.0;
      }
      final update = changed || (parent >= 0 && dirty[parent] != 0);
      dirty[i] = update ? 1 : 0;
      if (update) {
        if (parent < 0) {
          for (int c = 0; c < 12; c++) w[b + c] = l[b + c];
        } else {
          final p = parent * 12;
          for (int row = 0; row < 3; row++) {
            final q = row * 4;
            for (int c = 0; c < 4; c++) {
              w[b + q + c] =
                  w[p + q] * l[b + c] +
                  w[p + q + 1] * l[b + 4 + c] +
                  w[p + q + 2] * l[b + 8 + c] +
                  (c == 3 ? w[p + q + 3] : 0.0);
            }
          }
        }
      }
      final x = w[b + 3];
      final y = w[b + 7];
      final z = w[b + 11];
      if (x >= -21.0 &&
          x <= 21.0 &&
          y >= -21.0 &&
          y <= 21.0 &&
          z >= -11.0 &&
          z <= 41.0) {
        sum += 1.0 + i * 0.0001 + x * 0.01 + y * 0.02 + z * 0.03;
      }
    }
    return sum;
  }
}

class CollisionWorld implements GameWorld {
  Float64List x = Float64List(2048);
  Float64List y = Float64List(2048);
  Int32List heads = Int32List(1024);
  Int32List next = Int32List(2048);
  int frame = 0;
  CollisionWorld() {
    for (int i = 0; i < 2048; i++) {
      this.x[i] = ((i * 37) % 4096) * 0.03125 - 64.0;
      this.y[i] = ((i * 101) % 4096) * 0.03125 - 64.0;
    }
  }
  double tick() {
    this.frame++;
    final x = this.x;
    final y = this.y;
    final heads = this.heads;
    final next = this.next;
    for (int c = 0; c < 1024; c++) heads[c] = -1;
    for (int i = 0; i < 2048; i++) {
      x[i] += (i % 7 - 3) * 0.002;
      y[i] += (i % 11 - 5) * 0.002;
      if (x[i] >= 64.0) x[i] -= 128.0;
      if (x[i] < -64.0) x[i] += 128.0;
      if (y[i] >= 64.0) y[i] -= 128.0;
      if (y[i] < -64.0) y[i] += 128.0;
      final c =
          floorInt((y[i] + 64.0) * 0.25) * 32 + floorInt((x[i] + 64.0) * 0.25);
      next[i] = heads[c];
      heads[c] = i;
    }
    double sum = 0.0;
    for (int i = 0; i < 2048; i++) {
      final cx = floorInt((x[i] + 64.0) * 0.25);
      final cy = floorInt((y[i] + 64.0) * 0.25);
      for (int dy = -1; dy <= 1; dy++) {
        final yy = cy + dy;
        if (yy < 0 || yy >= 32) continue;
        for (int dx = -1; dx <= 1; dx++) {
          final xx = cx + dx;
          if (xx < 0 || xx >= 32) continue;
          int j = readInt(heads, yy * 32 + xx);
          while (j >= 0) {
            if (j > i) {
              final ax = x[i] - x[j];
              final ay = y[i] - y[j];
              if (ax * ax + ay * ay < 2.25) sum += (i + 1) * 3 + (j + 1) * 5;
            }
            j = readInt(next, j);
          }
        }
      }
    }
    return sum;
  }
}

class GameEvent {
  int entity = 0;
  int kind = 0;
  double amount = 0.0;
}

class EventWorld implements GameWorld {
  List<List<GameEvent>> ring = [];
  Float64List health = Float64List(4096);
  bool pooled = false;
  int frame = 0;
  EventWorld(bool pooled) {
    this.pooled = pooled;
    for (int i = 0; i < 4096; i++) this.health[i] = 50.0;
    for (int slot = 0; slot < 8; slot++) {
      final List<GameEvent> events = [];
      if (pooled) for (int j = 0; j < 2000; j++) events.add(GameEvent());
      this.ring.add(events);
    }
  }
  double tick() {
    final f = this.frame++;
    final slot = f % 8;
    final List<GameEvent> events = this.pooled ? this.ring[slot] : [];
    for (int j = 0; j < 2000; j++) {
      final e = this.pooled ? events[j] : GameEvent();
      e.entity = (j * 17 + f % 1024) % 4096;
      e.kind = j % 3;
      e.amount = (j % 13 + f % 7) * 0.125;
      if (!this.pooled) events.add(e);
    }
    this.ring[slot] = events;
    for (int j = 0; j < events.length; j++) {
      final e = events[j];
      var h = this.health[e.entity];
      if (e.kind == 0)
        h -= e.amount;
      else if (e.kind == 1)
        h += e.amount * 0.5;
      else
        h += e.amount * 0.125;
      if (h < 0.0) h = 100.0;
      if (h > 100.0) h = 0.0;
      this.health[e.entity] = h;
    }
    double sum = 0.0;
    for (int i = 0; i < 4096; i++) sum += this.health[i];
    if (f >= 7) {
      final older = this.ring[(slot + 1) % 8];
      for (int j = 0; j < 64; j++)
        sum += older[j].amount * (older[j].entity + 1);
    }
    return sum;
  }
}

GameWorld createWorld(int kind) {
  if (kind == 0) return ActorWorld();
  if (kind == 1) return ParticleWorld();
  if (kind == 2) return SceneWorld();
  if (kind == 3) return CollisionWorld();
  return EventWorld(kind == 5);
}

Float64List checkWorld(int kind) {
  final world = createWorld(kind);
  final checks = Float64List(2);
  for (int i = 0; i < 128; i++) {
    final value = world.tick();
    if (i == 7) checks[0] = value;
    if (i == 127) checks[1] = value;
  }
  return checks;
}

double warmSink = 0.0;
void warmWorld(int kind) {
  final world = createWorld(kind);
  final start = nowStamp();
  while (stampMs(nowStamp() - start) < 1000.0) warmSink += world.tick();
}

void measureGame(int kind, String name) {
  print('GAME_STAGE ' + name + ' checks');
  final before = checkWorld(kind);
  print('GAME_STAGE ' + name + ' warmup');
  warmWorld(kind);
  final world = createWorld(kind);
  final samples = Float64List(3000);
  double sink = 0.0;
  print('GAME_STAGE ' + name + ' measured');
  for (int frame = 0; frame < 3000; frame++) {
    final start = nowStamp();
    sink += world.tick();
    final end = nowStamp();
    samples[frame] = stampMs(end - start);
  }
  final after = checkWorld(kind);
  print(
    'GAME {"name":"' +
        name +
        '","check_before":[' +
        before.join(',') +
        '],"check_after":[' +
        after.join(',') +
        '],"sink":' +
        sink.toString() +
        ',"warm_sink":' +
        warmSink.toString() +
        ',"frames_ms":[' +
        samples.join(',') +
        ']}',
  );
}

void main(List<String> args) {
  final List<String> names = [
    'behaviours_10k',
    'particles_50k',
    'scene_8191',
    'collisions_2048',
    'events_alloc_2k',
    'events_pool_2k',
  ];
  for (int kind = 0; kind < names.length; kind++) {
    if (args.length == 0 || args[0] == names[kind])
      measureGame(kind, names[kind]);
  }
}
